  'udt.market.intro':
    'First come, first served: buy a bot at its price and it joins your roster at once. Prices are fixed for the market day; every market day brings new offers.',
  'udt.market.sold': 'sold',
  'udt.market.soldTo': 'sold to {tag}',
  'udt.market.yours': 'yours',
  'udt.market.buyTitle': 'Buy',
  'udt.market.price': 'Price',
  'udt.market.value': 'Market value',
  'udt.market.surcharge':
    'The price is the market value plus 10 % (weak), 20 % (middle) or 30 % (strong bots). Selling back pays 85 % of the value, at most what the bot cost (not while the bot plays in a drawn or running Dream Team tournament).',
  'udt.market.buy': 'Buy · {price}',
  'udt.market.buyConfirm':
    'Buy {name} for {price}? The bot joins your roster at once; from the next Monday it draws a salary.',
  'udt.market.cannotAfford': 'Not enough Neuro to spend.',
  'udt.market.full': 'Your roster is full ({max} bots): sell a bot first.',
  'udt.market.roster': 'Roster',
  'udt.trades.lead': 'Swap bots and Neuro with other managers: a {fee} % fee, offers run {h} h.',
  'udt.trades.rules':
    'Bought bots and the bots you made (also the starter) can be traded, from {lock} days after buying, making or trading; bots you made stay bots of their own at the new team (no salary – blueprint bots 75 % –, they keep developing) and you remain their breeder. Not while a bot plays in a drawn or running tournament or is nominated for the graduation. Fee {fee} % on what you receive · the smaller side is worth at least {bal} % of the other · every roster keeps at least one bot · offers run {h} h.',
  'udt.trades.blocked.nominated': 'nominated for the graduation',
  'udt.trades.own': 'made by its team: keeps developing, no or less salary',
  'udt.trades.noneTradable':
    'None of your bots can be traded now: a bot can be traded {lock} days after buying, making or trading, not while it plays or is nominated. You can still offer Neuro for a bot.',
  'udt.rename.label': 'New name',
  'udt.rename.button': 'Rename',
  'udt.rename.confirm': 'Rename {from} to {to}? This works only once.',
  'ok.udt.renamed': 'Renamed: the bot is called {name} now.',
  'ok.udt.signed':
    'Talent signed: it is in your roster now. You can rename it once for free (Academy › Own bots).',
  'ok.udt.apprentice': 'Apprentice taken on: it learned from its mentor.',
  'ok.udt.built': 'Bot built from the blueprint. You can rename it once for free.',
  'ok.udt.breakthrough': 'Breakthrough! Skill and potential +1.',
  'udt.help.button': 'How it works',
  'udt.help.bots.title': 'Get new bots',
  'udt.help.way.market.title': 'Market: buy at once',
  'udt.help.way.market.text':
    'Every market day brings new bots at a fixed price. Buy one and it joins your roster right away; first come, first served.',
  'udt.help.way.academy.title': 'Academy: raise your own',
  'udt.help.way.academy.text':
    'Scout three talents and sign one with a licence, or build a bot from a blueprint; an experienced bot (from level 3) can teach one of them as its apprentice. Starter, talents and apprentices draw no salary, blueprint bots 75 % of the normal one; bots you made develop with points and can be renamed once for free. Licences: as many as you like, each twice the price of the one before.',
  'udt.help.way.packs.title': 'Packs: traits and blueprints',
  'udt.help.way.packs.text':
    'Packs bring traits that make your bots stronger, and now and then a blueprint for the academy. In the trait workshop you reroll a card or upgrade it one rarity for Neuro and scrap.',
  'udt.help.way.trades.title': 'Trades: swap with managers',
  'udt.help.way.trades.text':
    'Swap bots and Neuro with other managers – bought ones and the ones you made, the starter too (one bot always stays). Bots you made keep their perks at the new team, and you stay their breeder.',
  'udt.help.bots.roster':
    'A roster holds up to 7 bots (5 play, 2 on the bench). Selling a bot back to the market pays 85 % of its value, at most what it cost (not while it plays in a drawn or running Dream Team tournament).',
  'udt.help.neuro.title': 'Neuro',
  'udt.help.neuro.text':
    "Neuro is the website's currency: you win it with bets and Dream Team rewards and can spend what is above the rescue floor. Neuro in bought bots count towards that floor: the rescue after a lost bet only tops up what is missing beyond them. Bought bots draw a salary every Monday; a bot whose salary cannot be paid goes on strike until a market day can collect what it is owed (a sale pays it too). Prices follow the economy index; salaries, standard packs and licences only its square root above 1 (at index 5 about ×2.2 instead of ×5), premium and elite packs even less (premium index^0.4, elite index^0.35: at index 5 about ×1.9 and ×1.8).",
  'udt.rename.once': 'Once per bot, free (the look can change any time).',
  'ok.udt.autoOn': 'Automatic sign-up on: {n} {n|tournament|tournaments} entered right away.',
