export const DICT: Record<Lang, Record<string, string>> = { en, de };

export function translate(
  lang: Lang,
  key: string,
  params?: Record<string, string | number>,
): string {
  let s = DICT[lang][key] ?? DICT.en[key] ?? key;
  if (!params) return s;
  // Plurals: "{n|Tag|Tage}" takes the first form for n = 1, else the second.
  s = s.replace(/\{(\w+)\|([^|{}]*)\|([^|{}]*)\}/g, (all, k: string, one: string, other: string) =>
    k in params ? (Number(params[k]) === 1 ? one : other) : all,
  );
  for (const [k, v] of Object.entries(params)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}
